import './style.css';
import {Game,BIOMES} from './game.js';
import {HEROES,MONSTERS,branchEffect,VERSION} from './roster.js';
import {Scene} from './scene.js';
import {Input} from './input.js';
import {readProgress,saveProgress} from './progress.js';
import {api,metric,ads} from './services.js';
import {AudioSys} from '../core/AudioSynth.js';
const $=id=>document.getElementById(id),progress=readProgress();
let game,scene,hero=HEROES[progress.selected]?progress.selected:'cinder',runToken=null,settled=false,lastFocus,toastTimer;
function save(){if(!saveProgress(progress))toast('Progress cannot be saved on this device.');}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function on(id,fn){$(id)?.addEventListener('click',fn);}
function modal(title,html){lastFocus=document.activeElement;$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').hidden=false;$('modal-body').querySelector('button')?.focus();}
function close(){$('modal').hidden=true;lastFocus?.focus?.();}
function art(h){return `background-position:${h.sprite%8/7*100}% ${Math.floor(h.sprite/8)/3*100}%`;}
function select(id){hero=id;progress.selected=id;const h=HEROES[id];$('selected-name').textContent=h.name;$('portrait').style.cssText=art(h);$('portrait-caption').textContent=`${h.name} / ${h.weapon}`;save();}
select(hero);$('records').hidden=progress.runs===0;
try{scene=new Scene($('world'));}catch(e){$('start').disabled=true;toast('WebGL is unavailable. Enable hardware acceleration.');console.error(e);}
function heroes(){modal('Eight souls. Eight oaths.',`<p class="muted">Complete expeditions to awaken new heroes. Every hero starts with equal progression.</p><div class="hero-grid">${Object.values(HEROES).map(h=>`<button class="hero-card ${h.id===hero?'selected':''}" data-hero="${h.id}" ${progress.runs<h.unlockRuns?'disabled':''}><div class="portrait" style="${art(h)}"></div><h3>${h.name}</h3><p>${h.trait}</p><small>${progress.runs<h.unlockRuns?`Complete ${h.unlockRuns} expeditions (${progress.runs}/${h.unlockRuns})`:h.weapon}</small></button>`).join('')}</div><button id="back">Return</button>`);document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{select(b.dataset.hero);close();});on('back',close);}
on('heroes',heroes);
function settings(){modal('Settings',`<label class="setting"><input type="checkbox" id="sound" ${progress.muted?'':'checked'}> Sound</label><label class="setting"><input type="checkbox" id="motion" ${progress.reduced?'checked':''}> Reduce motion</label><p class="muted">WASD / arrows: move · Space: dodge · R: signature<br>B: inspect build · Escape: pause · 1–3: choose blessing</p><button id="fullscreen">Fullscreen</button><button id="back">Return</button>`);$('sound').onchange=e=>{progress.muted=!e.target.checked;AudioSys.init();if(AudioSys.masterGain)AudioSys.masterGain.gain.value=progress.muted?0:.5;save();};$('motion').onchange=e=>{progress.reduced=e.target.checked;save();};on('fullscreen',()=>document.documentElement.requestFullscreen?.().catch(()=>toast('Fullscreen unavailable.')));on('back',close);}
on('settings',settings);
async function start(kind='solo'){if(!scene)return;$('start').disabled=true;try{let challenge;if(kind!=='solo'){challenge=await api('start',{kind});if(challenge.version!==VERSION)throw new Error('Challenge version is unavailable.');}runToken=challenge?.token||null;game=new Game({hero:challenge?.hero||hero,seed:challenge?.seed??crypto.getRandomValues(new Uint32Array(1))[0],ranked:!!challenge,modifier:challenge?.modifier});settled=false;close();$('menu').hidden=true;$('hud').hidden=false;document.body.classList.add('playing');AudioSys.init();if(AudioSys.masterGain)AudioSys.masterGain.gain.value=progress.muted?0:.5;if(!progress.muted)AudioSys.startMusic?.();metric('run_start');}catch(e){toast(e.message);}finally{$('start').disabled=false;}}
on('start',()=>start());
function settle(){if(!game||settled)return;settled=true;if(['dead','victory'].includes(game.state)||game.time>=60)progress.runs++;progress.gold+=game.gold;progress.totalKills+=game.kills;progress.bossKills+=game.bossKills;progress.records.push({version:VERSION,hero:game.hero,duration:Math.floor(game.time),kills:game.kills,gold:game.gold,score:game.score(),victory:game.state==='victory'});progress.records.sort((a,b)=>b.score-a.score);progress.records=progress.records.slice(0,10);save();}
function menu(){settle();game=null;close();$('menu').hidden=false;$('hud').hidden=true;$('records').hidden=progress.runs===0;document.body.classList.remove('playing');}
function resume(){close();game.state='playing';}
function pause(){if(!game||game.state!=='playing')return;game.state='paused';modal('A moment of silence',`<button id="resume" class="primary">Resume</button><button id="build">Inspect build</button><button id="quit">End expedition & return</button>`);on('resume',resume);on('build',build);on('quit',menu);}
function build(){if(!game||!['playing','paused'].includes(game.state))return;game.state='paused';const h=HEROES[game.hero];modal(`${h.name} / Your build`,`<p>${h.weapon} · ${h.trait}</p><div class="cards">${h.branches.map((name,i)=>`<div class="card"><small>BRANCH ${i+1} / ${game.player.ranks[i]} OF 3</small><h3>${name}</h3><p>${branchEffect(h.id,i,game.player.ranks[i])}</p><div class="ranks">${[1,2,3].map(n=>`<span class="${game.player.ranks[i]>=n?'lit':''}">${n}</span>`).join(' → ')}</div></div>`).join('')}</div><p class="muted">Damage dealt: ${Object.entries(game.damageLog).map(([k,v])=>`${k} ${Math.round(v).toLocaleString()}`).join(' · ')}</p><button id="resume" class="primary">Return to battle</button>`);on('resume',resume);}
function level(){modal(`Level ${game.player.level} / Choose your path`,`<p class="muted">Each branch has three ranks. The third transforms its effect.</p><div class="cards">${game.choices.map((c,i)=>`<button class="card upgrade" data-choice="${c.id}"><small>${i+1} / RANK ${c.rank+1} OF ${c.max}</small><h3>${c.name}</h3><p>${c.desc}</p><span>${c.connection}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(game.upgrade(b.dataset.choice))close();});}
async function finish(victory){settle();const result=progress.records.find(r=>r.hero===game.hero&&r.duration===Math.floor(game.time)),duration=Math.floor(game.time),token=runToken;runToken=null;metric('run_complete');modal(victory?'The last light endures':'The ember remembers',`<p>${victory?'Three guardians have fallen. The sanctuaries are silent.':'Every descent teaches you something.'}</p><div class="statline"><strong>${formatTime(game.time)}<small>SURVIVED</small></strong><strong>${game.kills}<small>SLAIN</small></strong><strong>${game.score().toLocaleString()}<small>SCORE</small></strong></div><p class="muted">${game.gold} gold recovered · ${game.bossKills} guardians defeated</p><p id="upload-status"></p><button id="again" class="primary">Descend again</button><button id="return">Return to camp</button>${!game.ranked&&ads.available()?'<button id="reward">Watch an ad · recover 50 gold</button>':''}`);on('again',()=>start());on('return',menu);let rewardPending=false;on('reward',async()=>{if(rewardPending)return;rewardPending=true;$('reward').disabled=true;if(await ads.reward()){progress.gold+=50;save();$('reward').textContent='50 gold recovered';}else{rewardPending=false;$('reward').disabled=false;}});if(token){const target=$('upload-status');try{await api('submit',{token,duration,kills:game.kills,gold:game.gold,victory});target.textContent='Challenge recorded.';}catch(e){target.textContent=`Score not submitted: ${e.message}`;}}if(!game?.ranked)ads.interstitial(duration,victory);}
async function records(kind='local'){modal('Expedition records',`<div class="row"><button id="local">This device</button><button id="daily">Daily</button><button id="weekly">Weekly</button></div><p id="board-status"></p><div id="record-list"></div><button id="back">Return</button>`);on('back',close);on('local',()=>records());on('daily',()=>records('daily'));on('weekly',()=>records('weekly'));const target=$('record-list'),status=$('board-status');try{const rows=kind==='local'?progress.records:(await api(`board&kind=${kind}`)).records;status.textContent=kind==='local'?`${progress.runs} expeditions · ${progress.gold} gold recovered`:'Same hero and seed for every challenger.';for(const r of rows){const p=document.createElement('p');p.textContent=`${HEROES[r.hero]?.name||'Unknown'} · ${formatTime(r.duration)} · ${r.score} points`;target.appendChild(p);}if(kind!=='local'){const b=document.createElement('button');b.textContent=`Play ${kind} challenge`;b.onclick=()=>start(kind);target.appendChild(b);}}catch(e){status.textContent=e.message;}}
on('records',()=>records());
function action(name,value){if(name==='fullscreen'){document.documentElement.requestFullscreen?.();return;}if(!game)return;if(name==='pause'){if(game.state==='playing')pause();else if(game.state==='paused')resume();}if(name==='autopause')pause();if(name==='dash'){const v=input.vector();game.dash(v.x,v.z);}if(name==='ultimate')game.ultimate();if(name==='shop')build();if(name==='choice'&&game.state==='upgrade'){const c=game.choices[value];if(c&&game.upgrade(c.id))close();}}
const input=new Input(action);document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('modal').hidden)return;const els=[...$('modal').querySelectorAll('button:not(:disabled),input,select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
function formatTime(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;}
function hud(){const p=game.player;$('realm').textContent=BIOMES[game.biome].name;$('time').textContent=formatTime(game.time);$('totals').textContent=`${game.kills} / ${game.gold}`;$('health-label').textContent=`VITALITY ${Math.ceil(p.hp)} / ${p.maxHp}`;$('health').max=p.maxHp;$('health').value=p.hp;$('level').textContent=`LEVEL ${p.level} / ${Math.floor(p.xp)} OF ${p.need} SOULS`;$('xp').value=p.xp/p.need;$('ultimate').textContent=p.ult>=100?`${HEROES[game.hero].ultName} [R]`:`Signature ${Math.floor(p.ult)}%`;$('dash').textContent=p.stamina>=34?'Dodge [Space]':'Recovering';const boss=game.enemies.find(e=>e.boss);$('boss').hidden=!boss;if(boss){$('boss-hp').value=boss.hp/boss.maxHp;$('boss-name').textContent=`${MONSTERS[boss.type].name} / Phase ${boss.phase}`;}$('guide').textContent=progress.runs===0?(game.time<10?'Move with WASD or the touch pad. Your weapon fires automatically.':game.time<22?'Dodge through danger with Space. Watch for amber warning rings.':game.time<35?'Collect pale soul crystals to grow your weapon.':''):'';}
let last=performance.now(),acc=0,hudClock=0;function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;acc+=dt;while(acc>=1/60){game?.update(1/60,input.vector());acc-=1/60;}if(game){for(const e of game.events.splice(0)){if(e.type==='level'){level();if(!progress.muted)AudioSys.playLevelUp?.();}if(e.type==='end')finish(e.victory);if(e.type==='boss')toast(`${e.name} awakens. Watch the windup.`);if(e.type==='region')toast(e.name);if(!progress.muted){if(e.type==='shoot')AudioSys.playShoot?.();if(e.type==='hurt')AudioSys.playHit?.();if(e.type==='dash')AudioSys.playDash?.();}}hudClock+=dt;if(hudClock>.1){hud();hudClock=0;}}scene?.draw(game,now/1000,hero,progress.reduced);requestAnimationFrame(frame);}requestAnimationFrame(frame);
if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(regs=>{const scope=new URL('./',location.href).href;for(const reg of regs)if(reg.scope===scope)reg.unregister();}).catch(()=>{});
if(import.meta.env.DEV)window.__soulEmber={get game(){return game;},get scene(){return scene;},start,action};
