 let advance=false;for(const e of this.enemies.filter(e=>e.hp<=0)){this.kills++;this.streak++;this.maxStreak=Math.max(this.streak,this.maxStreak);if(e.elite)this.elites++;p.ult=Math.min(100,p.ult+.5);this.drop('xp',e.x,e.z,e.xp*(e.elite?2:1)*h.soulYield);if(this.rng()<.4)this.drop('gold',e.x+.3,e.z,e.elite?8:1);if(this.rng()<.015)this.drop('potion',e.x,e.z,18);if(e.elite)this.drop('chest',e.x,e.z,12);this.corpses.push({...e,life:.65});if(e.boss){this.bossKills++;this.drop('potion',e.x,e.z,30);if(this.biome===2){this.state='victory';this.emit('end',{victory:true});}else advance=true;}}
